<?php
namespace App\Http\Requests\PublicChrome;
use App\Domain\PublicChrome\PublicLink; use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Validator;
class HeaderRequest extends FormRequest { public function authorize():bool{return true;} protected function prepareForValidation():void{$this->merge(['show_search'=>false,'show_language_switcher'=>false,'show_top_bar'=>$this->boolean('show_top_bar'),'sticky_header'=>$this->boolean('sticky_header'),'show_site_name'=>$this->boolean('show_site_name'),'show_primary_cta'=>$this->boolean('show_primary_cta')]);} public function rules():array{return ['show_top_bar'=>['boolean'],'sticky_header'=>['boolean'],'show_site_name'=>['boolean'],'show_search'=>['accepted:false'],'show_language_switcher'=>['accepted:false'],'show_primary_cta'=>['boolean'],'primary_cta_label'=>['nullable','string','max:80'],'primary_cta_url'=>['nullable','string','max:2048'],'primary_cta_target'=>['required','in:_self,_blank'],'primary_cta_style'=>['required','in:primary,secondary'],'top_bar_message'=>['nullable','string','max:240'],'support_label'=>['nullable','string','max:80'],'support_url'=>['nullable','string','max:2048'],'careers_label'=>['nullable','string','max:80'],'careers_url'=>['nullable','string','max:2048']];} public function after():array{return [function(Validator $v){foreach(['primary_cta','support','careers'] as $prefix){$url=$this->input($prefix.'_url');$label=$this->input($prefix.'_label');if(($url||$label)&&(!$url||!$label||!PublicLink::isSafeUrl($url)))$v->errors()->add($prefix.'_url','A label and safe relative or HTTP/HTTPS URL are required.');}}];} }
